const $ = (selector,root=document)=>root.querySelector(selector);
const $$ = (selector,root=document)=>[...root.querySelectorAll(selector)];
const escapeHtml = value => String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
let selectedCategory='全部', selectedLawyerArea='全部', activeRequest=null, toastTimer, dialogTrigger=null;

function routeTo(route){
  const valid=['home','exchange','lawyers','library']; if(!valid.includes(route)) route='home';
  $$('.page').forEach(page=>page.classList.toggle('active',page.id===`page-${route}`));
  $$('[data-route]').forEach(link=>{const active=link.dataset.route===route;link.classList.toggle('active',active);if(active)link.setAttribute('aria-current','page');else link.removeAttribute('aria-current')});
  window.scrollTo({top:0,behavior:'auto'});
}
function toast(message){const el=$('#toast');el.textContent=message;el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.hidden=true,3800)}
function openDialog(dialog,trigger){dialogTrigger=trigger||document.activeElement;dialog.showModal();const focusable=$('input,textarea,select',dialog)||$('button',dialog);if(focusable)focusable.focus()}
function closeDialog(dialog){dialog.close();if(dialogTrigger&&dialogTrigger.isConnected)dialogTrigger.focus()}
$$('[data-close]').forEach(button=>button.addEventListener('click',()=>closeDialog(button.closest('dialog'))));
$$('dialog').forEach(dialog=>dialog.addEventListener('click',event=>{if(event.target===dialog)closeDialog(dialog)}));
window.addEventListener('hashchange',()=>routeTo(location.hash.slice(1)));
$$('[data-go]').forEach(button=>button.addEventListener('click',()=>{location.hash=button.dataset.go;routeTo(button.dataset.go)}));
$$('[data-service]').forEach(button=>button.addEventListener('click',()=>{if(button.dataset.service==='document'){location.hash='home';$('#agentInput').value='我想起草一份法律文书，请引导我补充必要事实';$('#agentInput').focus();toast('已填入文书起草示例，请点击“开始梳理”')}else{location.hash='library';routeTo('library')}}));
$('#privacyButton').addEventListener('click',event=>openDialog($('#privacyDialog'),event.currentTarget));

function renderRequests(){
  const keyword=$('#requestSearch').value.trim().toLocaleLowerCase('zh-CN');
  const shown=requests.filter(item=>(selectedCategory==='全部'||item.category===selectedCategory)&&(!keyword||`${item.title} ${item.description} ${item.region}`.toLocaleLowerCase('zh-CN').includes(keyword)));
  $('#resultCount').textContent=`${shown.length} 条求取`;
  $('#emptyResults').hidden=shown.length!==0;
  $('#requestList').innerHTML=shown.map(item=>`<article class="request-card"><div><button type="button" class="request-title" data-request="${item.id}">${escapeHtml(item.title)}</button><p>${escapeHtml(item.description)}</p><div class="request-tags"><span class="soft-tag">${escapeHtml(item.category)}</span><span class="soft-tag">${escapeHtml(item.region)}</span>${item.verified?'<span class="verified-tag">✓ 平台核验</span>':''}<span class="soft-tag">${escapeHtml(item.updated)}</span></div></div><div class="request-side"><div class="reward ${item.reward===0?'free':''}">${item.reward===0?'免费互助':`¥ ${item.reward}<small>报酬意向</small>`}</div><button type="button" class="secondary-button" data-request="${item.id}">查看详情 →</button></div></article>`).join('');
  $$('[data-request]','#requestList').forEach(button=>button.addEventListener('click',()=>showRequest(Number(button.dataset.request),button)));
}
function showRequest(id,trigger){const item=requests.find(request=>request.id===id);if(!item)return;activeRequest=item;$('#detailTitle').textContent=item.title;$('#detailBody').innerHTML=`<p class="detail-summary">${escapeHtml(item.description)}</p><div class="detail-grid"><div>事项类别<strong>${escapeHtml(item.category)}</strong></div><div>相关地区<strong>${escapeHtml(item.region)}</strong></div><div>求取方<strong>${escapeHtml(item.owner)} ${item.verified?'· 平台核验':''}</strong></div><div>报酬意向<strong>${item.reward===0?'免费互助':`¥ ${item.reward} · 未托管`}</strong></div><div>希望回复时间<strong>${item.deadline||'未指定'}</strong></div><div>信息范围<strong>公开或有权提供的信息</strong></div></div><p class="detail-note">本条为虚构演示。平台核验仅表示主体与用途经平台复核；报酬意向不代表付款或托管。请勿提供非公开个人信息。</p><div class="dialog-actions"><button type="button" class="secondary-button" data-close>关闭</button><button type="button" class="primary-button" id="contactRequest">站内联系求取方</button></div>`;$('#detailBody [data-close]').addEventListener('click',()=>closeDialog($('#detailDialog')));$('#contactRequest').addEventListener('click',event=>{closeDialog($('#detailDialog'));$('#messageTitle').textContent=`联系${item.owner}`;$('#messageInput').value='';$('#messageError').hidden=true;openDialog($('#messageDialog'),trigger)});openDialog($('#detailDialog'),trigger)}
$$('.filter').forEach(button=>button.addEventListener('click',()=>{selectedCategory=button.dataset.filter;$$('.filter').forEach(item=>item.classList.toggle('active',item===button));renderRequests()}));
$('#requestSearch').addEventListener('input',event=>{$('#clearSearch').hidden=!event.target.value;renderRequests()});
$('#clearSearch').addEventListener('click',()=>{$('#requestSearch').value='';$('#clearSearch').hidden=true;renderRequests();$('#requestSearch').focus()});
$('#resetFilters').addEventListener('click',()=>{$('#requestSearch').value='';$('#clearSearch').hidden=true;selectedCategory='全部';$$('.filter').forEach(button=>button.classList.toggle('active',button.dataset.filter==='全部'));renderRequests();$('#requestSearch').focus()});
function setExchangeTab(tab){const provide=tab==='provide';$('#panelProvide').hidden=!provide;$('#panelRequest').hidden=provide;$('#tabProvide').classList.toggle('active',provide);$('#tabRequest').classList.toggle('active',!provide);$('#tabProvide').setAttribute('aria-selected',String(provide));$('#tabRequest').setAttribute('aria-selected',String(!provide))}
$('#tabProvide').addEventListener('click',()=>setExchangeTab('provide'));$('#tabRequest').addEventListener('click',()=>setExchangeTab('request'));
$$('.tab').forEach(button=>button.addEventListener('keydown',event=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const target=event.key==='ArrowLeft'||event.key==='Home'?'provide':'request';setExchangeTab(target);$(target==='provide'?'#tabProvide':'#tabRequest').focus()}));
function openPublish(event){openDialog($('#publishDialog'),event.currentTarget)}$('#openPublish').addEventListener('click',openPublish);$('#openPublishSecondary').addEventListener('click',openPublish);
function setFieldError(name,message){const input=$(`[name="${name}"]`,$('#publishForm'));const error=$(`#error-${name}`);if(!error)return;error.textContent=message;error.hidden=!message;input.setAttribute('aria-invalid',String(Boolean(message)));input.setAttribute('aria-describedby',error.id)}
$('#publishForm').addEventListener('submit',event=>{event.preventDefault();const form=event.currentTarget;const values={title:form.elements.namedItem('title').value.trim(),category:form.elements.namedItem('category').value,region:form.elements.namedItem('region').value.trim(),description:form.elements.namedItem('description').value.trim(),reward:Number(form.elements.namedItem('reward').value),deadline:form.elements.namedItem('deadline').value};let firstInvalid=null;const errors={title:values.title.length<5?'请填写至少 5 个字的标题。':'',category:!values.category?'请选择事项类别。':'',region:!values.region?'请填写相关地区。':'',description:values.description.length<20?'请至少用 20 个字说明信息范围和用途。':'',reward:form.elements.namedItem('reward').value===''||!Number.isFinite(values.reward)||values.reward<0||values.reward>100000?'请输入 0 到 100000 元之间的金额。':''};Object.entries(errors).forEach(([name,message])=>{setFieldError(name,message);if(message&&!firstInvalid)firstInvalid=$(`[name="${name}"]`,form)});if(firstInvalid){firstInvalid.focus();return}const item={...values,id:Date.now(),verified:false,owner:'我',updated:'刚刚'};$('#myRequestList').insertAdjacentHTML('afterbegin',`<div class="my-request-row"><strong>${escapeHtml(item.title)}</strong><small>演示草稿 · ${escapeHtml(item.category)} · ${item.reward===0?'免费互助':`¥ ${item.reward} 报酬意向`} · 真实产品发布前需审核</small></div>`);form.reset();Object.keys(errors).forEach(name=>setFieldError(name,''));closeDialog($('#publishDialog'));setExchangeTab('request');toast('演示求取已保存到当前页面')});
$('#sendMessage').addEventListener('click',()=>{const value=$('#messageInput').value.trim();if(value.length<10){$('#messageError').textContent='请至少用 10 个字说明可提供的信息和来源。';$('#messageError').hidden=false;$('#messageInput').focus();return}closeDialog($('#messageDialog'));toast('演示消息已生成；真实版会在站内发送')});
function renderLawyers(){const shown=lawyers.filter(lawyer=>selectedLawyerArea==='全部'||lawyer.areas.includes(selectedLawyerArea));$('#lawyerList').innerHTML=shown.map(lawyer=>`<article class="lawyer-card"><div class="lawyer-avatar">${escapeHtml(lawyer.name[0])}</div><div class="lawyer-main"><h2>${escapeHtml(lawyer.name)} <span class="verified-tag small">✓ 执业信息已核验</span></h2><p>${escapeHtml(lawyer.years)}执业 · ${escapeHtml(lawyer.firm)} · ${escapeHtml(lawyer.region)}</p><div class="lawyer-pills">${lawyer.areas.map(area=>`<span class="soft-tag">${escapeHtml(area)}</span>`).join('')}<span class="soft-tag">公开答疑 ${lawyer.answers}</span></div></div><button type="button" class="secondary-button" data-lawyer="${lawyer.id}">查看主页 →</button></article>`).join('');$$('[data-lawyer]','#lawyerList').forEach(button=>button.addEventListener('click',()=>showLawyer(Number(button.dataset.lawyer),button)))}
function showLawyer(id,trigger){const lawyer=lawyers.find(item=>item.id===id);if(!lawyer)return;$('#lawyerDetailName').textContent=lawyer.name;$('#lawyerDetailBody').innerHTML=`<p class="detail-summary">${escapeHtml(lawyer.firm)} · ${escapeHtml(lawyer.region)} · ${escapeHtml(lawyer.years)}执业</p><div class="verified-tag">✓ 执业信息已核验 · 演示状态</div><p class="detail-note">正式产品将展示执业证书的适度信息、核验来源、时间与有效状态；本页无真实律师身份或证书。</p><div class="lawyer-stats"><div class="lawyer-stat"><strong>${lawyer.services}</strong><span>平台服务</span></div><div class="lawyer-stat"><strong>${lawyer.answers}</strong><span>公开答疑</span></div><div class="lawyer-stat"><strong>${lawyer.solved}</strong><span>解决求取</span></div></div><div class="profile-section"><h3>主营业务</h3><p>${lawyer.areas.map(escapeHtml).join(' · ')}</p></div><div class="profile-section"><h3>代表案例</h3><p>${escapeHtml(lawyer.cases)}</p></div><div class="profile-section"><h3>公开社交账号</h3><p>${escapeHtml(lawyer.social)}</p></div><div class="dialog-actions"><button type="button" class="secondary-button" data-close>关闭</button><button type="button" class="primary-button" id="contactLawyer">咨询律师</button></div>`;$('#lawyerDetailBody [data-close]').addEventListener('click',()=>closeDialog($('#lawyerDialog')));$('#contactLawyer').addEventListener('click',()=>toast('正式版将核验登录与律师状态后发起站内咨询'));openDialog($('#lawyerDialog'),trigger)}
$$('.lawyer-filter').forEach(button=>button.addEventListener('click',()=>{selectedLawyerArea=button.dataset.area;$$('.lawyer-filter').forEach(item=>item.classList.toggle('active',item===button));renderLawyers()}));
$$('[data-prompt]').forEach(button=>button.addEventListener('click',()=>{$('#agentInput').value=button.dataset.prompt;$('#agentInput').focus()}));
$('#agentForm').addEventListener('submit',event=>{event.preventDefault();const question=$('#agentInput').value.trim();if(question.length<6){$('#agentError').textContent='请至少用 6 个字描述你的问题。';$('#agentError').hidden=false;$('#agentInput').focus();return}$('#agentError').hidden=true;const answer=$('#agentAnswer');answer.hidden=false;answer.innerHTML=`<h3>先把问题拆成三个部分</h3><p>你想了解的是：<strong>${escapeHtml(question)}</strong></p><p>① 发生了什么、在什么地区和时间；② 手上有哪些合同、记录或官方材料；③ 你希望达到什么结果。补齐这些信息后，才能核对适用条文和办理步骤。</p><p>下一步：先查看<a href="https://flk.npc.gov.cn/search" target="_blank" rel="noopener noreferrer">国家法律法规数据库</a>中的现行规定；需要个案判断时可找律师或公共法律服务渠道。</p><small>演示回答 · 未进行实时法条检索，不构成个案法律意见</small>`;answer.scrollIntoView({behavior:'smooth',block:'nearest'})});
renderRequests();renderLawyers();routeTo(location.hash.slice(1)||'home');
